def similaridade_cosseno(a, b):
    # -1 (opostos) a 1 (idênticos)
    return a @ b / (
        np.linalg.norm(a) * np.linalg.norm(b)
    )

rei = np.array([0.9, 0.8, 0.1])
banana = np.array([0.1, 0.2, 0.95])
print(similaridade_cosseno(rei, banana))
# ~0.33 -> pouco parecidos

def softmax(z):
    e = np.exp(z - z.max())  # evita overflow
    return e / e.sum()

logits = np.array([2.0, 1.0, 0.1])
print(softmax(logits))
# [0.659 0.242 0.099] -> soma 1
